        { name: "عَمَلٌ يُصَدِّقُ الإيمانَ", items: ["أُتْقِنُ واجِبي", "أَصْدُقُ في كَلامي"] },
        { name: "عَمَلٌ يُخالِفُ الإيمانَ", items: ["أَغُشُّ في الاِمْتِحانِ", "أُخْفي عَيْبَ الْبِضاعَةِ"] }
